query getAutomaticDiscountNode($id: ID!) {
  discountNode(id: $id) {
    id
    discount {
      ... on DiscountAutomaticApp {
        discountId
        title
        appDiscountType {
          appKey
          functionId
        }
        combinesWith {
          orderDiscounts
          productDiscounts
          shippingDiscounts
          productDiscountsWithTagsOnSameCartLine
        }
        status
        discountClasses
        startsAt
        endsAt
        appliesOnOneTimePurchase
        appliesOnSubscription
        recurringCycleLimit
        tags
      }
    }
    metafields(first: 100) {
      nodes {
        id
        namespace
        key
        type
        value
      }
    }
  }
}

mutation discountAutomaticAppUpdate($automaticAppDiscount: DiscountAutomaticAppInput!, $id: ID!) {
  discountAutomaticAppUpdate(automaticAppDiscount: $automaticAppDiscount, id: $id) {
    automaticAppDiscount {
      discountId
      title
      appDiscountType {
        appKey
        functionId
      }
      combinesWith {
        orderDiscounts
        productDiscounts
        shippingDiscounts
        productDiscountsWithTagsOnSameCartLine
      }
      status
      discountClasses
      startsAt
      endsAt
      appliesOnOneTimePurchase
      appliesOnSubscription
      recurringCycleLimit
    }
    userErrors {
      field
      message
    }
  }
}
